public class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        Map<String, FB_Shipment_Event__e> latestEventByOrder = new Map<String, FB_Shipment_Event__e>();

        if (events != null) {
            for (FB_Shipment_Event__e event : events) {
                if (event == null || String.isBlank(event.Order_Number__c)) {
                    continue;
                }

                String orderNumber = event.Order_Number__c.trim().toUpperCase();
                latestEventByOrder.put(orderNumber, event);
            }
        }

        if (latestEventByOrder.isEmpty()) {
            return;
        }

        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        List<FB_Sales_Order__c> orders = [
            SELECT Id,
                   Order_Number__c,
                   Status__c,
                   Tracking_Number__c,
                   Carrier__c,
                   Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :latestEventByOrder.keySet()
        ];

        Date today = Date.today();

        for (FB_Sales_Order__c order : orders) {
            if (order.Status__c == 'Cancelled') {
                continue;
            }

            String orderKey = order.Order_Number__c == null ? '' : order.Order_Number__c.trim().toUpperCase();
            FB_Shipment_Event__e event = latestEventByOrder.get(orderKey);

            if (event == null) {
                continue;
            }

            order.Status__c = 'Shipped';
            order.Tracking_Number__c = event.Tracking_Number__c;
            order.Carrier__c = event.Carrier__c;
            order.Shipped_Date__c = today;
            ordersToUpdate.add(order);
        }

        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
