public class LogPurgeJob implements Schedulable {
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        DateTime now = DateTime.now();
        DateTime thirtyDaysAgo = now.addDays(-30);
        DateTime oneHundredEightyDaysAgo = now.addDays(-180);
        String errorLevel = 'ERROR';

        String soql = 'SELECT Id FROM FB_Integration_Log__c WHERE (Level__c = null OR Level__c != :errorLevel) AND CreatedDate < :thirtyDaysAgo';
        List<Object> bindVars = new List<Object>{ errorLevel, thirtyDaysAgo };
        QueryLocator locator = Database.getQueryLocator(soql, bindVars);
        deleteInBatches(locator);

        soql = 'SELECT Id FROM FB_Integration_Log__c WHERE Level__c = :errorLevel AND CreatedDate < :oneHundredEightyDaysAgo';
        bindVars = new List<Object>{ errorLevel, oneHundredEightyDaysAgo };
        locator = Database.getQueryLocator(soql, bindVars);
        deleteInBatches(locator);
    }

    private static void deleteInBatches(QueryLocator locator) {
        Integer batchSize = 1000;

        try {
            while (locator.hasNext()) {
                List<SObject> batch = locator.fetch(batchSize);

                if (batch != null && !batch.isEmpty()) {
                    delete batch;
                }
            }
        } finally {
            locator.close();
        }
    }

    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        String cronExpression = 'CRON_TZ[America/Chicago] 0 0 2 ? * ?';

        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }
}
