        validateAmountIsNotNegative();
    }

    protected override void beforeUpdate() {
        validateAmountIsNotNegative();
        validateAmountNotChangedOnWonOpportunity();
    }

    private void validateAmountIsNotNegative() {
        Opportunity opportunity = (Opportunity) this.sObject;

        if (opportunity.Amount != null && opportunity.Amount < 0) {
            this.error('Amount cannot be negative.', opportunity, 'Amount');
        }
    }

    private void validateAmountNotChangedOnWonOpportunity() {
        Opportunity opportunity = (Opportunity) this.sObject;
        Opportunity oldOpportunity = (Opportunity) Trigger.oldMap.get(opportunity.Id);

        if (oldOpportunity != null && oldOpportunity.Stage == 'Closed Won') {
            if (opportunity.Amount != oldOpportunity.Amount) {
                this.error('Amount cannot change on a won opportunity.', opportunity, 'Amount');
            }
        }
    }
}
