    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        if (maxRecords != null && maxRecords <= 0) {
            return new List<Opportunity>();
        }

        List<Id> accountIdList = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountIdList.add(accountId);
            }
        }

        if (accountIdList.isEmpty()) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = new fflib_QueryFactory(getSObjectType(), getSObjectFieldList());
        queryFactory.addSelectField('Account.Name');
        queryFactory.addWhereCondition('IsClosed', false);
        queryFactory.addWhereCondition('AccountId', accountIdList, fflib_QueryFactory.Operator.In);
        queryFactory.orderBy('Amount', SortOrder.Descending);
        queryFactory.orderBy('CloseDate', SortOrder.Ascending);

        if (maxRecords != null) {
            queryFactory.setLimit(maxRecords);
        }

        return (List<Opportunity>) queryFactory.getQuery().execute();
    }
}
