    public List<Schema.SObjectField> getSObjectFieldList() {
        return getAccountFieldList();
    }

    private List<Schema.SObjectField> getAccountFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<String> seenFieldNames = new Set<String>{
            'id',
            'name',
            'industry'
        };

        Schema.FieldSet creditReviewFieldSet = Account.SObjectType.getDescribe().getFieldSet('Credit_Review');
        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember fieldSetMember : creditReviewFieldSet.getFields()) {
                Schema.SObjectField field = fieldSetMember.getField();
                String fieldName = field.getDescribe().getName().toLowerCase();
                if (!seenFieldNames.contains(fieldName)) {
                    seenFieldNames.add(fieldName);
                    fields.add(field);
                }
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        AccountsSelector selector = new AccountsSelector();
        selector.setChildRelationship('Contacts', new ContactsSelector().getSObjectFieldList());
        return (List<Account>) selector.selectSObjectsById(accountIds);
    }
