public class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> accounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return accounts;
        }

        fflib_SObjectUnitOfWork sowu = new fflib_SObjectUnitOfWork();

        for (Map.Entry<String, List<String>> entry : contactLastNamesByAccountName.entrySet()) {
            Account account = new Account(Name = entry.getKey());
            sowu.addNew(account);
            accounts.add(account);

            List<String> lastNames = entry.getValue();
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact contact = new Contact(
                    LastName = lastName,
                    AccountId = account.Id
                );
                sowu.addNew(contact);
            }
        }

        sowu.commitWork();

        return accounts;
    }
}
