public class OpportunityWinService {
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);
        if (opportunities == null || opportunities.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName != STAGE_CLOSED_WON) {
                opportunitiesToClose.add(opportunity);
            }
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_IUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.start();

        for (Opportunity opportunity : opportunitiesToClose) {
            opportunity.StageName = STAGE_CLOSED_WON;
            opportunity.CloseDate = System.today();

            uow.register(opportunity);

            Deal_Won__e dealWonEvent = new Deal_Won__e();
            dealWonEvent.Opportunity_Id__c = String.valueOf(opportunity.Id);
            dealWonEvent.Amount__c = opportunity.Amount;

            uow.publish(dealWonEvent);
        }

        uow.commit();

        return opportunitiesToClose.size();
    }
}
